/**
 * Loads the shared, read-only dictionary dataset. It's a static JSON file
 * (`public/dictionary/shared.json`, generated by `npm run dictionary:import`)
 * rather than a Firestore collection: it's the same for every user, never
 * written at runtime (so no user can overwrite a shared definition), costs
 * no Firestore reads, and is cached by the browser/CDN.
 *
 * Fetched at most once per page load and shared by every caller — the
 * Dictionary tab today, and any future in-lesson lookup — so lookups never
 * trigger extra network requests.
 */
import type { SharedDictionaryFile, SharedEntry } from "./types";

export const SHARED_DICTIONARY_URL = "/dictionary/shared.json";

let cached: Promise<SharedEntry[]> | null = null;

export function loadSharedDictionary(): Promise<SharedEntry[]> {
  if (!cached) {
    cached = fetch(SHARED_DICTIONARY_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`Couldn't load the dictionary (HTTP ${res.status}).`);
        return res.json() as Promise<SharedDictionaryFile>;
      })
      .then((file) => file.entries)
      .catch((err) => {
        cached = null; // allow a retry on the next call
        throw err;
      });
  }
  return cached;
}
